const out = document.getElementById('out');
const results = [];
class Fail extends Error {}
const fail = msg => { throw new Fail(msg); };
/** 공유 판 `G`(아래 「새 게임 · 직렬화」)의 처음 모습 — 판이 서면 채운다. 그 전의 단정은 판을 모른다 */
let G0 = null;
function check(name, fn) {
    try {
        const r = fn();
        results.push({ name, ok: r !== false, msg: typeof r === 'string' ? r : '' });
    } catch (e) {
        results.push({ name, ok: false, msg: e instanceof Fail ? e.message : String(e && e.stack ? e.stack.split('\n').slice(0, 2).join(' ') : e) });
    }
    // **공유 판은 읽기 전용이다** [2026-09-22 · 구조 감사] — 바꾼 단정은 그 자리에서 빨간불이고 판을 새로 깐다(뒤 단정이 흔적을 안 밟게).
    //   돌려 쓰던 때는 반지 단정이 끼워 둔 반지를 낀 채 뒤의 전투 단정 39개가 싸웠고 분해 단정은 그 반지를 분해했다 —
    //   단정 하나를 지우면 무관한 단정의 조건이 바뀌었다. 판을 바꾸는 단정은 `freshG()` 로 제 판을 만든다
    if (G0 !== null && JSON.stringify(G) !== G0) {
        const last = results[results.length - 1];
        last.ok = false;
        last.msg = `공유 판 G 를 바꿨다 — 판을 바꾸는 단정은 freshG() 로 제 판을 만든다 · ${last.msg}`;
        G = freshG();
        G0 = JSON.stringify(G);
    }
}
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const NOW = 1_700_000_000_000;      // 고정 시각 — 테스트는 시계를 읽지 않는다
/** 손으로 만든 장비 — 접사만 지정하고 나머지는 최소 골격 (드롭 굴림과 무관하게 계산을 시험한다) */
const mkItem = (slot, affixes, extra = {}) =>
    ({ uid: null, slot, rarity: 'magic', ilvl: 1, name: { ko: slot, en: slot }, implicit: null, affixes, sins: ['wrath'], ...extra });

await loadData('../data/');
const SYS = buildSystems(D);
const B = D.balance;
const WG = D.weaponGroups;
/** 그 판의 장을 n장까지 연다 — 앞 장 보스 칸(`game.chapterGate`)을 첫 단 기록에 넣는다 (장은 앞 장 보스가 연다 · R319) */
const openChapters = (g, n) => {
    for (let ch = 2; ch <= n; ch++) { const s = SYS.game.chapterGate(ch); if (s != null && !g.progress.cleared.includes(s)) g.progress.cleared.push(s); }
    return g;
};
check('결투장: 인간 3인 상대 · 평균 레벨 · 전열/후열 · 원본 독립', () => {
    const g = SYS.game.newGame(72, SYS.hero.rollCandidates(makeRng(72), 3), 0);
    g.heroes.slice(0, 3).forEach((h, i) => { h.level = 2 + i; });
    const before = JSON.stringify(g);
    const team = SYS.arena.snapshotTeam(g.heroes.slice(0, 3), g.items);
    const enemy = SYS.arena.rollOpponent(team, makeRng(73));
    if (enemy.length !== 3 || enemy.some(p => p.hero.level !== 3 || !p.gear.some(it => it.slot === 'weapon')))
        fail('상대 인원/레벨/무기');
    const result = SYS.arena.fight(team, enemy, makeRng(74));
    const round = result.timeline.find(e => e.e === 'round');
    if (round.enemies.some((e, i) => !e.hero?.name || e.rank !== (i === 0 ? 0 : 1))) fail('상대 신원/진형');
    if (JSON.stringify(g) !== before) fail('원본 세이브가 변했다');
    team[0].hero.stats.str = -1;
    return JSON.stringify(g) === before;
});
check('결투장: 같은 입력/시드 = 같은 결과 · 단판 · 보상/도감 없음 · loadout 없으면 물약 칸 0', () => {
    const g = SYS.game.newGame(81, SYS.hero.rollCandidates(makeRng(81), 3), 0);
    const team = SYS.arena.snapshotTeam(g.heroes.slice(0, 3), g.items);
    const enemy = SYS.arena.rollOpponent(team, makeRng(82));
    const before = JSON.stringify([team, enemy]);
    const a = SYS.arena.fight(team, enemy, makeRng(83));
    const b = SYS.arena.fight(team, enemy, makeRng(83));
    return JSON.stringify(a) === JSON.stringify(b) && JSON.stringify([team, enemy]) === before
        && a.rounds.length === 1 && a.xpTotal === 0 && a.gold === 0 && !Object.keys(a.kills).length
        && !a.drops.length && !a.blueprints.length && a.potion.max === 0 && a.potion.used === 0
        && a.timeline.some(e => e.e === 'end');
});
check('결투장: 고른 편성의 전술 · 물약 칸을 싣는다 · 전술 몫은 원정과 같다 · 세이브 불변', () => {
    const g = SYS.game.newGame(101, SYS.hero.rollCandidates(makeRng(101), 3), 0);
    for (const h of g.heroes.slice(0, 3)) if (!SYS.game.partyOf(g).includes(h.uid)) SYS.game.toggleParty(g, h.uid, 0);
    const heroes = SYS.game.partyOf(g).map(uid => g.heroes.find(h => h.uid === uid));
    if (heroes.length !== 3) fail(`편성 인원 ${heroes.length}`);
    const before = JSON.stringify(g);
    const lo = SYS.game.arenaLoadout(g);
    // 도감이 빈 새 게임이라 원정의 전투 능력치(전술 · 도감 포함)와 한 글자도 같아야 한다
    const team = SYS.arena.snapshotTeam(heroes, g.items, {}, lo);
    if (team.some((p, i) => JSON.stringify(p.combat) !== JSON.stringify(SYS.game.heroCombat(g, heroes[i])))) fail('전술 몫이 원정과 다르다');
    const r = SYS.arena.fight(team, SYS.arena.rollOpponent(team, makeRng(102)), makeRng(103), lo);
    if (r.potion.max !== lo.slotMax || JSON.stringify(r.potion.slots) !== JSON.stringify(lo.potions)) fail(`물약 칸 ${JSON.stringify(r.potion)}`);
    return JSON.stringify(g) === before;
});
check('결투장: 3명 미만/중복 선택 거절', () => {
    const g = SYS.game.newGame(91, SYS.hero.rollCandidates(makeRng(91), 3), 0);
    let rejected = 0;
    for (const hs of [g.heroes.slice(0, 2), [g.heroes[0], g.heroes[0], g.heroes[1]]]) {
        try { SYS.arena.snapshotTeam(hs, g.items); } catch { rejected++; }
    }
    return rejected === 2;
});
/* 결투장 두 갈래 (2026-10-17 · arena_design §0 · §7 · INTERFACE §2-17) — 등급 AI 상대 · 팀 코드 · 적법성 검사 */
/** 등급 팀 → 팀 코드 재료(영웅 · 장비 표 · 랭크) — 스냅샷의 영웅이 아직 장비 uid 를 들고 있다 */
const arenaParts = team => ({
    heroes: team.map(p => p.hero),
    items: Object.fromEntries(team.flatMap(p => p.gear.map(it => [it.uid, it]))),
    ranks: Object.fromEntries(team.map(p => [p.uid, p.rank])),
});
/** 단정이 손으로 다시 세우는 식 — 코드와 같은 식을 쓰면 서로를 못 잡는다 */
const advPointsAt = lv => lv < B.advance_unlock_level ? 0 : 1 + Math.floor((lv - B.advance_unlock_level) / B.advance_point_interval);
const skillCapEnd = B.skillbook_upgrade_max;   // 책 업그레이드 상한 — 끝 하나 (2026-10-20 · R293 · ~~skill_codex_level.csv 마지막 행~~)
const upCap = SYS.game.limitsOf({ buildings: Object.fromEntries(SYS.construction.list.map(b => [b.id, b.maxRank])) }).upgrade;   // 건물을 다 지었을 때의 강화 상한
check('결투장: 등급 상대 — 레벨 · 착용 위치 전부 · 아이템 레벨 · 강화 · 마스터리 · 책 · 전직 · 스킬 업그레이드가 등급과 게임 규칙대로 (arena_design §7)', () => {
    const tiers = SYS.arena.tiers;
    if (!tiers.length) fail('등급이 없다');
    for (const t of tiers) {
        const team = SYS.arena.rollTierOpponent(t.id, makeRng(500 + t.order), ['아무개']);
        const tag = `${t.id}:`;
        if (team.length !== 3 || new Set(team.map(p => p.hero.cls)).size !== 3) fail(`${tag} 직업 셋이 다르지 않다`);
        const names = team.map(p => p.hero.name?.ko ?? p.hero.name);
        if (new Set(names).size !== 3 || names.includes('아무개')) fail(`${tag} 이름 겹침 ${names}`);
        const front = team.filter(p => p.rank === 0);
        if (front.length !== 1 || team.some(p => p.combat.hp_max > front[0].combat.hp_max)) fail(`${tag} 전열은 최대 HP 가 가장 큰 하나`);
        for (const p of team) {
            const h = p.hero, who = `${tag}${h.cls}`;
            if (h.level !== t.level) fail(`${who} 레벨 ${h.level}`);
            if (p.gear.length !== D.equipSlots.length || D.equipSlots.some(s => !h.equipped[s.id])) fail(`${who} 빈 위치`);
            for (const it of p.gear) {
                if (it.ilvl !== t.level) fail(`${who} ${it.slot} 아이템 레벨 ${it.ilvl}`);
                if ((it.up ?? 0) !== (SYS.item.upgradeable(it) ? Math.min(t.up, upCap) : 0)) fail(`${who} ${it.slot} 강화 ${it.up}`);
            }
            // 마스터리 — 레벨이 준 포인트를 다 썼다(남았다면 찍을 노드가 없어서다)
            const spent = Object.values(h.mastery).reduce((s, r) => s + r, 0);
            const budget = (t.level - 1) * B.mastery_point_per_level;
            const open = SYS.hero.masteryNodesFor(h).filter(n => n.unlockLevel <= h.level && (h.mastery[n.id] ?? 0) < n.maxRank && SYS.hero.gateOn(n, p.gear, h));
            if (spent + (h.masteryPoints ?? 0) !== budget || ((h.masteryPoints ?? 0) > 0 && open.length)) fail(`${who} 마스터리 ${spent}/${budget} 남음 ${h.masteryPoints}`);
            if ((t.level >= B.skillbook_learn_level) !== !!h.bookSkill) fail(`${who} 책 ${h.bookSkill}`);
            if ((t.level >= B.advance_unlock_level) !== !!h.advanceSkill) fail(`${who} 전직 ${h.advance}/${h.advanceSkill}`);
            if (h.advanceSkill && 1 + (h.advanceUp ?? 0) !== advPointsAt(t.level)) fail(`${who} 전직 포인트 ${1 + (h.advanceUp ?? 0)} ≠ ${advPointsAt(t.level)}`);
            const wantLv = Math.min(t.skillUp, skillCapEnd);
            for (const id of [h.innate, h.bookSkill].filter(Boolean))
                if ((h.skillLv?.[id] ?? 0) !== wantLv) fail(`${who} ${id} 업그레이드 ${h.skillLv?.[id]} ≠ ${wantLv}`);
            if (p.actives.length !== [h.innate, h.bookSkill, h.advanceSkill].filter(Boolean).length) fail(`${who} 액티브 칸 ${p.actives.length}`);
        }
    }
    return `등급 ${tiers.map(t => `${t.id} Lv${t.level}`).join(' · ')}`;
});
check('결투장: 등급 상대 — 같은 시드 = 같은 팀 · 다른 시드 = 다른 팀 · 모르는 등급은 던진다', () => {
    const id = SYS.arena.tiers[SYS.arena.tiers.length - 1].id;
    const a = SYS.arena.rollTierOpponent(id, makeRng(7)), b = SYS.arena.rollTierOpponent(id, makeRng(7)), c = SYS.arena.rollTierOpponent(id, makeRng(8));
    if (!eq(a, b)) fail('같은 시드가 다른 팀');
    if (eq(a, c)) fail('다른 시드가 같은 팀');
    try { SYS.arena.rollTierOpponent('없는등급', makeRng(1)); } catch { return true; }
    fail('모르는 등급을 받았다');
});
check('결투장: 생성한 등급 팀은 적법성 검사를 지난다 — 검사기가 AI 상대의 상한이다 (arena_design §2 · §7)', () => {
    let n = 0;
    for (const t of SYS.arena.tiers) for (const seed of [11, 12, 13]) {
        const { heroes, items, ranks } = arenaParts(SYS.arena.rollTierOpponent(t.id, makeRng(seed * 100 + t.order)));
        const problems = SYS.arena.validateTeam(SYS.arena.exportTeam(heroes, items, ranks));
        if (problems.length) fail(`${t.id} 시드 ${seed} — ${JSON.stringify(problems)}`);
        n++;
    }
    return `${n} 팀 통과`;
});
check('결투장: 팀 코드 — 내보내고 들이면 같은 능력치 · 같은 스킬 · 같은 결과 · 원본 불변 (INTERFACE §2-17)', () => {
    const g = SYS.game.newGame(131, SYS.hero.rollCandidates(makeRng(131), 3), 0);
    const mine = g.heroes.slice(0, 3);
    const before = JSON.stringify(g);
    const ranks = { [mine[0].uid]: 0, [mine[1].uid]: 1, [mine[2].uid]: 1 };
    // 운반은 문자열이다 — 직렬화 왕복을 거친 것을 들인다
    const payload = JSON.parse(JSON.stringify(SYS.arena.exportTeam(mine, g.items, ranks)));
    if (payload.heroes.some(e => 'uid' in e.hero || e.gear.some(x => 'uid' in x.item) || 'combat' in e)) fail('uid · 능력치가 실렸다');
    const got = SYS.arena.importTeam(payload);
    if (!got.ok) fail(`새 게임 팀이 검사에 걸렸다 — ${JSON.stringify(got.problems)}`);
    const direct = SYS.arena.snapshotTeam(mine, g.items, ranks);
    got.team.forEach((p, i) => {
        if (!eq(p.combat, direct[i].combat)) fail(`${i} 능력치가 다르다`);
        if (!eq(p.actives, direct[i].actives) || p.rank !== direct[i].rank) fail(`${i} 스킬 · 진형이 다르다`);
    });
    const enemy = SYS.arena.rollTierOpponent(SYS.arena.tiers[0].id, makeRng(132));
    if (!eq(SYS.arena.fight(got.team, enemy, makeRng(133)), SYS.arena.fight(got.team, enemy, makeRng(133)))) fail('같은 시드가 다른 결과');
    return JSON.stringify(g) === before;
});
check('결투장: 검사기 — 판 · 직업 · 레벨 · 마스터리 · 전직 · 위치 · 강화 · 옵션 범위를 어기면 그 사유로 거절한다 (arena_design §2)', () => {
    const base = SYS.arena.exportTeam(...Object.values(arenaParts(SYS.arena.rollTierOpponent(SYS.arena.tiers[0].id, makeRng(141)))));
    const codesOf = mutate => { const p = JSON.parse(JSON.stringify(base)); mutate(p); return SYS.arena.validateTeam(p).map(x => x.code); };
    const expect = (code, mutate, why) => { if (!codesOf(mutate).includes(code)) fail(`${why} → ${code} 가 안 나왔다 (${codesOf(mutate)})`); };
    if (SYS.arena.validateTeam(base).length) fail('기준 팀이 이미 걸린다');
    expect('format', p => { p.v = 999; }, '판');
    expect('format', p => { p.heroes.pop(); }, '인원');
    const notMain = D.classes.map(c => c.id).find(c => !SYS.hero.mainClasses.includes(c));
    if (notMain) expect('class', p => { p.heroes[0].hero.cls = notMain; }, '본편 밖 직업');
    expect('level', p => { p.heroes[0].hero.level = B.hero_level_cap + 1; }, '만렙 초과');
    expect('stats', p => { const k = Object.keys(p.heroes[0].hero.stats)[0]; p.heroes[0].hero.stats[k] = B.hero_attr_max + 1; }, '능력치 상한 초과');
    expect('masteryPoints', p => {
        const h = p.heroes[0].hero;
        h.mastery = Object.fromEntries(SYS.hero.masteryNodesFor(h).filter(n => n.unlockLevel <= h.level).map(n => [n.id, n.maxRank]));
    }, '포인트 초과');
    expect('mastery', p => { p.heroes[0].hero.mastery = { 없는노드: 1 }; }, '트리 밖 노드');
    expect('advance', p => {
        const h = p.heroes[0].hero;
        h.advance = (D.advanceRows ?? []).find(r => r.class_id === h.cls)?.advance_id ?? 'x';   // 등급 첫 줄은 전직 레벨 아래다
    }, '전직 레벨 미달');
    expect('slot', p => { const g = p.heroes[0].gear; const w = g.find(x => x.pos === 'weapon'), a = g.find(x => x.pos === 'armor'); [w.item, a.item] = [a.item, w.item]; }, '위치와 부위가 다르다');
    expect('up', p => { p.heroes[0].gear.find(x => x.item.slot === 'weapon').item.up = 99; }, '강화 상한 초과');
    expect('up', p => { p.heroes[0].gear.find(x => x.item.slot === 'ring').item.up = 1; }, '반지 강화');
    expect('option', p => {
        for (const e of p.heroes) for (const x of e.gear) for (let k = 0; k < (x.item.affixes ?? []).length; k++) {
            const r = SYS.item.optionRange(x.item, k);
            if (r) { x.item.affixes[k].v = Math.max(r.min, r.max) + 1000; return; }
        }
        fail('범위를 아는 옵션 줄이 하나도 없다');
    }, '옵션 범위 밖');
    expect('reqLevel', p => { const x = p.heroes[0].gear.find(y => y.item.slot === 'weapon'); x.item.ilvl = B.hero_level_cap; }, '착용 요구 미달');
    // 받은 문자열은 화면 HTML 로 들어간다 — 태그를 여는 이름 · 장비 이름 · 이상한 초상 id 를 막는다
    expect('text', p => { p.heroes[0].hero.name = '<img src=x onerror=alert(1)>'; }, '이름에 태그');
    expect('text', p => { p.heroes[1].gear[0].item.name = { ko: 'a"b', en: 'x' }; }, '장비 이름에 따옴표');
    expect('format', p => { p.heroes[0].hero.face = 'x" onerror="alert(1)'; }, '초상 id 모양');
    return true;
});
/* 콜로세움 사다리 · 결투장 ELO (2026-10-18 · arena_design §7 · §8 · INTERFACE §2-7 · §2-17) */
check('콜로세움: 사다리 — 등급 층 수만큼 이어 붙고 · 등급 첫 층 = 등급 행 · 층은 다음 등급 쪽으로 오른다 · 마지막 층만 승급전', () => {
    const T = SYS.arena.tiers, F = SYS.arena.floors;
    if (F.length !== T.reduce((s, t) => s + t.floors, 0)) fail(`층 수 ${F.length}`);
    if (F.some((f, i) => f.no !== i + 1)) fail('층 번호가 1 부터 이어지지 않는다');
    T.forEach((t, i) => {
        const mine = F.filter(f => f.tier === t.id);
        const first = mine[0].kit;
        if (first.level !== t.level || first.up !== t.up || first.skillUp !== t.skillUp) fail(`${t.id} 첫 층 차림 ${JSON.stringify(first)}`);
        if (mine.filter(f => f.gate).length !== 1 || !mine.at(-1).gate) fail(`${t.id} 승급전은 마지막 층 하나`);
        // 손으로 다시 세운 잇기 — 코드와 같은 식을 쓰면 서로를 못 잡는다
        const N = T[i + 1] ?? t;
        mine.forEach((f, k) => {
            const want = Math.round(t.level + (N.level - t.level) * k / t.floors);
            if (f.kit.level !== want) fail(`${t.id} ${k + 1}층 레벨 ${f.kit.level} ≠ ${want}`);
        });
    });
    for (let i = 1; i < F.length; i++) if (F[i].kit.level < F[i - 1].kit.level) fail(`${F[i].no}층이 앞 층보다 레벨이 낮다`);
    return `${F.length}층 · ${T.map(t => `${t.id} ${t.floors}`).join(' · ')}`;
});
check('콜로세움: 층 상대 — 같은 층 = 같은 팀(시드를 안 받는다) · 층의 차림대로 · 검사기를 지난다 · 모르는 층은 던진다', () => {
    const F = SYS.arena.floors;
    for (const f of [F[0], F[Math.floor(F.length / 2)], F.at(-1)]) {
        const a = SYS.arena.rollFloorOpponent(f.no), b = SYS.arena.rollFloorOpponent(f.no);
        if (!eq(a, b)) fail(`${f.no}층이 부를 때마다 다르다`);
        if (a.some(p => p.hero.level !== f.kit.level || p.gear.some(it => it.ilvl !== f.kit.level))) fail(`${f.no}층 레벨이 차림과 다르다`);
        const problems = SYS.arena.validateTeam(SYS.arena.exportTeam(...Object.values(arenaParts(a))));
        if (problems.length) fail(`${f.no}층 — ${JSON.stringify(problems)}`);
    }
    if (eq(SYS.arena.rollFloorOpponent(1), SYS.arena.rollFloorOpponent(2))) fail('1층과 2층이 같은 팀');
    try { SYS.arena.rollFloorOpponent(F.length + 1); } catch { return true; }
    fail('없는 층을 받았다');
});
check('결투장: 레이팅 → 리그 · 차림 — 문턱에서 등급이 바뀌고 · 사이는 고르게 · 첫 문턱 아래는 레벨만 낮고 · 끝 위는 그대로 (arena_design §8)', () => {
    const T = SYS.arena.tiers;
    T.forEach((t, i) => {
        if (SYS.arena.tierOfRating(t.ratingMin) !== t.id) fail(`${t.ratingMin} → ${SYS.arena.tierOfRating(t.ratingMin)} ≠ ${t.id}`);
        if (i > 0 && SYS.arena.tierOfRating(t.ratingMin - 1) !== T[i - 1].id) fail(`${t.ratingMin - 1} 은 앞 등급`);
        const k = SYS.arena.kitOfRating(t.ratingMin);
        if (k.level !== t.level || k.up !== t.up || k.skillUp !== t.skillUp) fail(`${t.id} 문턱의 차림 ${JSON.stringify(k)}`);
    });
    const [a, b] = T;
    const mid = SYS.arena.kitOfRating((a.ratingMin + b.ratingMin) / 2);
    if (mid.level !== Math.round((a.level + b.level) / 2)) fail(`가운데 레벨 ${mid.level}`);
    const low = SYS.arena.kitOfRating(a.ratingMin - (b.ratingMin - a.ratingMin));
    if (low.level !== Math.max(1, Math.round(a.level - (b.level - a.level))) || low.up !== a.up) fail(`첫 문턱 아래 ${JSON.stringify(low)}`);
    if (SYS.arena.kitOfRating(-1e6).level !== 1) fail('아무리 낮아도 레벨 1');
    const top = T.at(-1), over = SYS.arena.kitOfRating(top.ratingMin + 1e6);
    if (over.level !== top.level || SYS.arena.tierOfRating(top.ratingMin + 1e6) !== top.id) fail(`끝 위 ${JSON.stringify(over)}`);
    return true;
});
check('결투장: 상대 후보 — 아래 · 비슷 · 위 셋 · 간격 ± 흔들림 안 · 그 레이팅의 차림 · 이름이 안 겹친다 · 같은 시드 = 같은 셋', () => {
    const r = B.arena_elo_start + 150;
    const c = SYS.arena.rollRatedCandidates(r, makeRng(61), ['아무개']);
    if (c.length !== 3) fail(`후보 ${c.length}`);
    c.forEach((x, i) => {
        const centre = r + (i - 1) * B.arena_pick_spread;
        if (Math.abs(x.rating - centre) > B.arena_pick_jitter) fail(`후보 ${i} 레이팅 ${x.rating} (가운데 ${centre})`);
        if (x.tier !== SYS.arena.tierOfRating(x.rating)) fail(`후보 ${i} 리그`);
        if (x.team.some(p => p.hero.level !== SYS.arena.kitOfRating(x.rating).level)) fail(`후보 ${i} 레벨`);
    });
    if (!(c[0].rating < c[1].rating && c[1].rating < c[2].rating)) fail(`순서 ${c.map(x => x.rating)}`);
    const names = c.flatMap(x => x.team.map(p => p.hero.name?.ko ?? p.hero.name));
    if (new Set(names).size !== names.length || names.includes('아무개')) fail(`이름 겹침 ${names}`);
    if (!eq(c, SYS.arena.rollRatedCandidates(r, makeRng(61), ['아무개']))) fail('같은 시드가 다른 셋');
    return c.map(x => `${x.rating}(${x.tier})`).join(' · ');
});
check('결투장: ELO — 시작값 · 같은 레이팅이면 이기면 +K/2 · 지면 −K/2 · 센 상대는 얻는 게 크다 · 싸운 순간 적힌다 · 0 아래로 안 간다 (arena_design §8)', () => {
    const g = SYS.game.newGame(171, SYS.hero.rollCandidates(makeRng(171), 3), 0);
    const s0 = SYS.game.arenaState(g);
    if (s0.rating !== B.arena_elo_start || s0.peak !== s0.rating || s0.win + s0.draw + s0.loss !== 0) fail(`시작 ${JSON.stringify(s0)}`);
    // 손으로 다시 세운 표준 ELO
    const elo = (me, opp, s) => Math.round(B.arena_elo_k * (s - 1 / (1 + 10 ** ((opp - me) / B.arena_elo_scale))));
    const even = SYS.game.arenaStakes(g, s0.rating);
    if (even.win !== elo(s0.rating, s0.rating, 1) || even.loss !== elo(s0.rating, s0.rating, 0) || even.draw !== 0) fail(`같은 레이팅 ${JSON.stringify(even)}`);
    const up = SYS.game.arenaStakes(g, s0.rating + 200), down = SYS.game.arenaStakes(g, s0.rating - 200);
    if (!(up.win > even.win && down.win < even.win && up.loss > even.loss)) fail(`센 상대 ${JSON.stringify(up)} · 약한 상대 ${JSON.stringify(down)}`);
    const r1 = SYS.game.arenaRecord(g, s0.rating + 200, 'win');
    if (!r1.ok || r1.delta !== up.win || g.arena.rating !== s0.rating + up.win || g.arena.win !== 1 || g.arena.peak !== g.arena.rating) fail(`이긴 기록 ${JSON.stringify(r1)} ${JSON.stringify(g.arena)}`);
    const r2 = SYS.game.arenaRecord(g, g.arena.rating, 'loss');
    if (g.arena.peak !== r1.after || g.arena.rating !== r1.after + r2.delta || g.arena.loss !== 1) fail(`진 기록 ${JSON.stringify(g.arena)}`);
    if (SYS.game.arenaRecord(g, 1000, 'tie').err !== 'outcome' || SYS.game.arenaRecord(g, NaN, 'win').err !== 'opp') fail('틀린 입력을 받았다');
    g.arena.rating = 3;
    SYS.game.arenaRecord(g, 3, 'loss');
    if (g.arena.rating !== 0) fail(`0 아래 ${g.arena.rating}`);
    return `±${even.win} · 강 +${up.win}/${up.loss} · 약 +${down.win}/${down.loss}`;
});
check('콜로세움: 오른 층 — 열린 가장 높은 층을 이기면 한 층 · 다시 이기기 · 지기는 그대로 · 안 열린 층은 거절 · 세이브 왕복 (INTERFACE §2-7 · §4)', () => {
    const g = SYS.game.newGame(172, SYS.hero.rollCandidates(makeRng(172), 3), 0);
    const st = () => SYS.game.colosseumState(g);
    if (st().cleared !== 0 || st().next !== 1) fail(`시작 ${JSON.stringify(st())}`);
    if (SYS.game.colosseumRecord(g, 2, true).err !== 'locked') fail('안 열린 층');
    if (SYS.game.colosseumRecord(g, 0, true).err !== 'floor') fail('0층');
    if (SYS.game.colosseumRecord(g, 1, false).advanced || st().cleared !== 0) fail('지고 올랐다');
    if (!SYS.game.colosseumRecord(g, 1, true).advanced || st().cleared !== 1) fail('이기고 안 올랐다');
    if (SYS.game.colosseumRecord(g, 1, true).advanced || st().cleared !== 1) fail('깬 층을 다시 이기고 올랐다');
    SYS.game.colosseumRecord(g, 2, true);
    SYS.game.arenaRecord(g, 1200, 'win');
    const back = SYS.game.deserialize(JSON.parse(JSON.stringify(SYS.game.serialize(g, 1))));
    if (back.colosseum.cleared !== 2 || !eq(back.arena, g.arena)) fail(`왕복 ${JSON.stringify(back.colosseum)} ${JSON.stringify(back.arena)}`);
    // 필드가 없는 옛 세이브 · 망가진 값 — 시작값으로 연다
    const old = JSON.parse(JSON.stringify(SYS.game.serialize(g, 1)));
    delete old.arena; old.colosseum = { cleared: -3 };
    const o = SYS.game.deserialize(old);
    if (o.arena.rating !== B.arena_elo_start || o.arena.win !== 0 || o.colosseum.cleared !== 0) fail(`옛 세이브 ${JSON.stringify(o.arena)} ${JSON.stringify(o.colosseum)}`);
    return true;
});
const AGROUP = D.armorGroups;                    // armor_group.csv — {slot: {groupId: def}} · 갑옷군 3갈래 (2026-09-16 · R107) + 투구 · 장갑 · 신발 갈래 (2026-09-18)
/** 무기 피해 가운데 — 구간 직선의 누적합 (R105). 단정이 공식을 손으로 다시 세운다: 코드와 같은 식을 쓰면 서로를 못 잡는다 */
const bandMid = ilvl => {
    let m = B.weapon_atk_base;
    for (let n = 2; n <= ilvl; n++) m += B[`weapon_atk_band${Math.min(8, Math.floor((n - 1) / B.weapon_atk_band_levels) + 1)}_unit`];
    return m;
};

