    if (count.rng !== 0) fail(`자폭이 rng 를 ${count.rng}회 썼다`);
    rt.fire(me, 'on_death', 3);
    if (log.filter(e => e.e === 'blast').length !== 2) fail('한 유닛이 두 번 터졌다 — on_death 는 once 다');
