    if (heals.length !== 1 || heals[0].d !== 'p0' || heals[0].amt !== want || a.u.hp !== 100 + want) fail(`회복 ${JSON.stringify(heals)} · HP ${a.u.hp} — 자신에게 ${want}`);
    if (run({ hp: 990 }).u.hp !== 1000) fail('최대 HP 를 넘었다');
