    old.items[uid].proc = { trigger: 'hit', skill: 'mag_focus', v: 0.1 };
    old.joins = [{ no: 1, hero: { ...JSON.parse(JSON.stringify(b)), uid: 'j1', innate: 'mag_frozenwall' }, arrivedAt: NOW, leavesAt: NOW + 1e9 }];
    const s = SYS.game.deserialize(old);
