    if (!eq(A.skillLv, { war_ironskin: 3, mag_fireball: 1 })) fail(`스킬 레벨 ${JSON.stringify(A.skillLv)} — 겹치면 큰 쪽`);
    if (!eq(A.skillOrder, ['mag_fireball', 'war_ironskin'])) fail(`칸 순서 ${A.skillOrder}`);
