    const other = D.difficultyList?.find?.(x => x.id !== diff)?.id ?? Object.keys(D.difficulties ?? {}).find(id => id !== diff);
    if (other && SYS.game.bossRespawnAt(g, 1051, other) !== null) fail(`다른 단(${other})에 기록이 번졌다`);
